public boolean shouldPrintMessage(int timestamp, String message) {
    // Validate input
    if (message == null || timestamp < 0) {
        return false;
    }

    // Assume a class-level HashMap<String, Integer> called 'lastTimestampMap' holds
    // the most recent timestamp for each message.
    Integer lastTimestamp = lastTimestampMap.get(message);

    // If the message has never been printed, or it was printed more than 10 seconds ago,
    // allow printing and record the current timestamp.
    if (lastTimestamp == null || (timestamp - lastTimestamp) >= 10) {
        lastTimestampMap.put(message, timestamp);
        return true;
    }

    // Otherwise the message should not be printed.
    return false;
}

