private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    try {
        if (str == null && suffix == null) {
            return true;
        }
        if (str == null || suffix == null) {
            return false;
        }
        if (suffix.isEmpty()) {
            return true;
        }
        int strLen = str.length();
        int sufLen = suffix.length();
        if (sufLen > strLen) {
            return false;
        }
        if (ignoreCase) {
            return str.regionMatches(true, strLen - sufLen, suffix, 0, sufLen);
        } else {
            return str.endsWith(suffix);
        }
    } catch (Exception e) {
        // In case of unexpected runtime exception, fall back to false
        return false;
    }
}

