private int parseEndOfLine(String headerPart, int end) {
    // Validate parameters.
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart must not be null");
    }
    if (end < -1 || end >= headerPart.length()) {
        throw new IllegalArgumentException(
                "end index out of bounds: " + end + ", length: " + headerPart.length());
    }

    // Start searching from the next character after the last processed byte.
    int start = end + 1;
    for (int i = start; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            // Return the index of the '\r' which marks the start of the CRLF sequence.
            return i;
        }
    }

    // Handle case where the header ends with a single '\r' without a following '\n'.
    if (start < headerPart.length() && headerPart.charAt(start) == '\r') {
        return start;
    }

    // If no CRLF sequence found, return -1.
    return -1;
}

