private static boolean isParameterSeparator(final char c) {
    // Character.isWhitespace includes space, tab, newline, carriage return, etc.
    if (Character.isWhitespace(c)) {
        return true;
    }
    // Common separators that typically indicate the end of a parameter name.
    switch (c) {
        case ',':
        case ';':
        case ':':
        case '=':
            return true;
        default:
            // Anything that is not a letter, digit, underscore or dash is considered a separator.
            if (!Character.isLetterOrDigit(c) && c != '_' && c != '-') {
                return true;
            }
            return false;
    }
}

