        throw new IllegalArgumentException("Target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    try {
        // Number of vertices in each partition; choose 3 for a simple K3,3
        final int leftSize = 3;
        final int rightSize = 3;

        // Lists to keep track of partition vertices
        final List<V> leftVertices = new java.util.ArrayList<>(leftSize);
        final List<V> rightVertices = new java.util.ArrayList<>(rightSize);

        // Create vertices for the left partition
        for (int i = 0; i < leftSize; i++) {
            // Vertices are represented as Strings; cast to V
            @SuppressWarnings("unchecked")
            V vertex = (V) ("U" + i);
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
            // Store in result map with key
            resultMap.put("U" + i, vertex);
            leftVertices.add(vertex);
        }

        // Create vertices for the right partition
        for (int j = 0; j < rightSize; j++) {
            @SuppressWarnings("unchecked")
            V vertex = (V) ("V" + j);
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
            resultMap.put("V" + j, vertex);
            rightVertices.add(vertex);
        }

        // Add edges between every pair of left and right vertices
        for (V u : leftVertices) {
            for (V v : rightVertices) {
                if (!target.containsEdge(u, v)) {
