    if (minLabel == 0) {
        return;
    }

    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    if (sourceBucket == null || sourceBucket.isEmpty()) {
        // Nothing to move
        return;
    }

    Set<Integer> targetBucket = bucketsByLabel.get(0);
    if (targetBucket == null) {
        // Defensive: create a new bucket if it does not exist yet
        targetBucket = new LinkedHashSet<>();
        bucketsByLabel.set(0, targetBucket);
    }

    // Move all vertices from source to target, updating labels
    for (Integer vertex : sourceBucket) {
