    List<Integer> suffix = new ArrayList<>(size);
    long total = 0;
    long running = 0;
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null element at index " + i);
        }
        int intVal = val.intValue();
        total += intVal;
        running += intVal;
        suffix.add(0, (int) running);
    }
    return new Pair<>(suffix, total);
}

