private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null.");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null.");
    }
    // An empty set or a single vertex trivially forms a clique.
    if (vertices.size() <= 1) {
        return true;
    }

    // Check that every pair of distinct vertices has an edge between them.
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue; // skip self‑loops
            }
            try {
                E edge = graph.getEdge(v1, v2);
                if (edge == null) {
                    return false;
                }
            } catch (IllegalArgumentException e) {
                // Typically thrown if one of the vertices isn't in the graph.
                throw new IllegalArgumentException("Both vertices must be present in the graph.", e);
            } catch (RuntimeException e) {
                // Propagate any other runtime issues.
                throw e;
            }
        }
    }
    return true;
}

