private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Validate parameters
    if (bb == null || sb == null) {
        throw new NullPointerException("ByteBuffer and StringBuilder must not be null");
    }
    // Check input index bounds
    if (i < 0 || i >= bb.limit()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + i);
    }
    try {
        // Read first byte
        int b1 = bb.get(i) & 0xFF;
        // ASCII (single-byte)
        if ((b1 & 0x80) == 0) {
            sb.append((char) b1);
            return i + 1;
        }
        int bytesNeeded;
        int codepoint;
        if ((b1 & 0xE0) == 0xC0) {            // 110xxxxx
            bytesNeeded = 1;
            codepoint = b1 & 0x1F;
        } else if ((b1 & 0xF0) == 0xE0) {     // 1110xxxx
            bytesNeeded = 2;
            codepoint = b1 & 0x0F;
        } else if ((b1 & 0xF8) == 0xF0) {     // 11110xxx
            bytesNeeded = 3;
            codepoint = b1 & 0x07;
        } else { // Invalid leading byte for UTF-8
            return i;
        }
        // Ensure there's enough bytes remaining
        if (i + 1 + bytesNeeded > bb.limit()) {
            return i; // cannot decode incomplete sequence
        }
        // Process continuation bytes
        for (int j = 1; j <= bytesNeeded; j++) {
            int cont = bb.get(i + j) & 0xFF;
            if ((cont & 0xC0) != 0x80) {
                return i; // invalid continuation byte
            }
            codepoint = (codepoint << 6) | (cont & 0x3F);
        }
        // Append decoded codepoint (handle surrogate pairs if necessary)
        if (codepoint <= 0xFFFF) {
            sb.append((char) codepoint);
        } else {
            int u = codepoint - 0x10000;
            sb.append((char) ((u >> 10) + 0xD800));
            sb.append((char) ((u & 0x3FF) + 0xDC00));
        }
        return i + 1 + bytesNeeded;
    } catch (Exception e) {
        // In case of any unexpected exception, return original index
        return i;
    }
