public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }

    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }

    // Remove a single leading '/' if present (absolute path).  For relative paths
    // this will have no effect.
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    // Split the path into segments.  Empty segments caused by '//' are ignored.
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segment = part;
        if (decode) {
            try {
                segment = URLDecoder.decode(part, "UTF-8");
            } catch (Exception e) {
                // If decoding fails, fall back to the raw segment.
                // No further action needed.
            }
        }
        segments.add(new PathSegmentImpl(segment));
    }

    return segments;
}

