public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath Vector cannot be null");
    }
    if (dir == null) {
        throw new IllegalArgumentException("Directory path cannot be null");
    }

    File dirFile = new File(dir);
    if (!dirFile.exists()) {
        throw new IllegalArgumentException("Directory does not exist: " + dir);
    }
    if (!dirFile.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a directory: " + dir);
    }

    File[] files = dirFile.listFiles();
    if (files == null) {
        // I/O error; nothing to add
        return;
    }

    for (File file : files) {
        if (file.isFile() && file.getName().toLowerCase().endsWith(".jar")) {
            try {
                cpV.add(file.toURI().toURL());
            } catch (MalformedURLException e) {
                // Skip files that cannot be represented as a URL
            }
        }
    }
}

