public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    // If either string is empty, no meaningful occurrences can be found
    if (sub.isEmpty() || str.isEmpty()) {
        return 0;
    }
    int count = 0;
    int index = 0;
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        // Move forward one character to allow overlapping occurrences
        index++;
    }
    return count;
}

