    // The actual ThreadLocal stack is maintained by the NDC class itself
    // (usually as a private static ThreadLocal field).  Here we rely on
    // that field being named THREAD_LOCAL_NDC.  If it is not present,
    // the method will simply return the empty string.
    try {
        java.lang.reflect.Field field = NDC.class.getDeclaredField("THREAD_LOCAL_NDC");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        java.lang.ThreadLocal<java.util.Deque<String>> tl =
                (java.lang.ThreadLocal<java.util.Deque<String>>) field.get(null);
        java.util.Deque<String> stack = tl != null ? tl.get() : null;
        if (stack == null || stack.isEmpty()) {
            return "";
        }
        return stack.peek();
    } catch (NoSuchFieldException | IllegalAccessException | IllegalArgumentException | ClassCastException e) {
        // If reflection fails or the stack is not as expected, return empty string.
        return "";
    }
}

