protected List<TimeRange> buildTimeRanges(long start, long end){
    // Validate input: end must not be less than start
    if (end < start) {
        throw new IllegalArgumentException("End time must be greater than or equal to start time");
    }

    // Special case: zero-length range
    if (start == end) {
        List<TimeRange> zeroRanges = new ArrayList<>();
        zeroRanges.add(new TimeRange(start, end));
        return zeroRanges;
    }

    // The constant that limits the duration of each split segment
    // (Assumed to be defined elsewhere in the class)
    long limit = FETCH_DATA_DURATION;

    // If the limit is non-positive, treat the whole interval as one range
    if (limit <= 0) {
        List<TimeRange> singleRange = new ArrayList<>();
        singleRange.add(new TimeRange(start, end));
        return singleRange;
    }

    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;

    while (currentStart < end) {
        // Remaining time to be processed
        long remaining = end - currentStart;
        // Decide the size of the next segment
        long segment = Math.min(limit, remaining);
        long currentEnd = currentStart + segment;
        // Add the new segment to the list
        ranges.add(new TimeRange(currentStart, currentEnd));
        // Move to the next start point
        currentStart = currentEnd;
    }

    return ranges;
}

