static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    String ts = Long.toString(timeBucket);
    if(ts.length() != 8){
        throw new IllegalArgumentException("timeBucket must be an 8-digit YYYYMMDD value");
    }
    int year;
    int month;
    int day;
    try{
        year = Integer.parseInt(ts.substring(0,4));
        month = Integer.parseInt(ts.substring(4,6));
        day = Integer.parseInt(ts.substring(6,8));
    }catch(NumberFormatException e){
        throw new IllegalArgumentException("timeBucket contains non‑digit characters", e);
    }
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("month out of range: " + month);
    }
    // simple days in month check; does not account for leap year but is sufficient for many cases
    int[] daysInMonth = {0,31,28,31,30,31,30,31,31,30,31,30,31};
    // Does not adjust for Feb 29 on leap years
    if(day < 1 || day > daysInMonth[month]){
        throw new IllegalArgumentException("day out of range for month: " + day);
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

