public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> result = new ArrayList<>();
    try {
        // Obtain current profiles list; if null or empty, return empty result
        List<?> profiles = getCurrentProfiles();
        if (profiles == null || profiles.isEmpty()) {
            return result;
        }

        // Obtain segment start offsets; if not provided, create a single full-range SequenceRange
        List<Integer> offsets = getSegmentOffsets();
        if (offsets == null || offsets.isEmpty()) {
            result.add(new SequenceRange(0, profiles.size() - 1));
            return result;
        }

        // Sort offsets to handle unsorted input and ensure uniqueness
        offsets.sort(Integer::compareTo);
        int lastOffset = -1;

        for (int i = 0; i < offsets.size(); i++) {
            int start = offsets.get(i);

            // Validate start index
            if (start < 0 || start >= profiles.size() || start <= lastOffset) {
                continue; // Skip invalid or duplicate offsets
            }

            int end;
            if (i + 1 < offsets.size()) {
                end = offsets.get(i + 1) - 1;
                // Ensure the following offset is greater than current start
                if (end < start) {
                    continue; // Skip malformed range
                }
            } else {
                end = profiles.size() - 1; // Last range extends to the end
            }

            // Cap end to the last valid index
            if (end >= profiles.size()) {
                end = profiles.size() - 1;
            }

            result.add(new SequenceRange(start, end));
            lastOffset = start;
        }
    } catch (Exception ex) {
        // Wrap any unchecked exception in a RuntimeException with context
        throw new RuntimeException("Unable to build sequence ranges", ex);
    }
    return result;
}

