public static int nextPrime(int desiredCapacity) {
    // Handle invalid or small inputs
    if (desiredCapacity < 2) {
        return 2;
    }
    long candidate = desiredCapacity;
    if (candidate < 2) {
        candidate = 2;
    }
    // threshold for closeness (11% of desired capacity)
    double threshold = 1.11;
    long maxCandidateAllowed = (long) Math.floor(desiredCapacity * threshold) + 1;
    while (candidate <= Integer.MAX_VALUE) {
        if (isPrime((int) candidate)) {
            if (desiredCapacity >= 1000 && candidate > maxCandidateAllowed) {
                // candidate is too far, keep looking
            } else {
                return (int) candidate;
            }
        }
        candidate++;
    }
    // Fallback: if we exceed bounds, return Integer.MAX_VALUE
    return Integer.MAX_VALUE;
}

/** Fast primality test for positive integers. */
private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int i = 5;
    int w = 2;
    while (i * (long) i <= n) {
        if (n % i == 0) return false;
        i += w;
        w = 6 - w;
    }
    return true;
}

